This motivates, for any $\delta>0$, to perform the scaling
\begin{equation}
	\label{eq:52}
	\tilde{\fN}_j \vcentcolon=\frac{\fN_j}{\sqrt{\beta+\delta}},\quad\text{with}\quad \beta \coloneqq \frac{1}{2\sigma_{\text{min}}(\fA)}\sum_{j=1}^{M}\sigma_1(\fN_j)^2,\quad j=1,\ldots M;
\end{equation}
